'use strict';
/* Offline-only, dependency-free interaction prototype. No network calls or persistent storage. */
const $ = s => document.querySelector(s);
const esc = input => String(input ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (id,cls='icon') => `<svg class="${cls}" aria-hidden="true"><use href="#i-${id}"></use></svg>`;
const badge = (name,tone='') => `<span class="badge ${tone}">${esc(name)}</span>`;
const names = {overview:'Übersicht',chat:'Chat',knowledge:'Wissensbasis',memory:'Gedächtnis',agents:'Agenten',models:'Modelle',system:'Systemstatus',settings:'Einstellungen'};
const state = {page:'overview',project:'Persönlich',model:'qwen3:1.7b',compact:false,memFilter:'Alle',docQuery:'',docScope:'Alle',agentFilter:'Alle',modal:null,search:'',chat:[],demoNotes:[],tools:{memory_search:true,memory_remember:false,memory_forget:false},docAdded:[],conversation:0};
const sampleDocs = [
 {name:'systemarchitektur.md',scope:'Private AI Pipeline',type:'Markdown',updated:'Beispiel',size:'14 KB'},
 {name:'gateway-api.md',scope:'Private AI Pipeline',type:'Markdown',updated:'Beispiel',size:'9 KB'},
 {name:'compose-sicherheit.md',scope:'Private AI Pipeline',type:'Markdown',updated:'Beispiel',size:'6 KB'},
 {name:'skyhub-notizen.txt',scope:'SkyHub-Next',type:'Text',updated:'Beispiel',size:'3 KB'},
 {name:'mcp-schnittstellen.md',scope:'Hermes-Agent',type:'Markdown',updated:'Beispiel',size:'11 KB'}
];
const sampleMem = [
 {id:1,title:'Projektkonfiguration',desc:'Lokale Modelle sollen ohne Cloud-Fallback angesprochen werden.',scope:'Private AI Pipeline',time:'Beispieldatensatz'},
 {id:2,title:'Entwicklungsregel',desc:'Externe Geräte und bestehende Pi-Dienste bei Tests nicht verändern.',scope:'Private AI Pipeline',time:'Beispieldatensatz'},
 {id:3,title:'Drohnenplattform',desc:'SkyHub-Next nutzt eine getrennte lokale Entwicklungsumgebung.',scope:'SkyHub-Next',time:'Beispieldatensatz'}
];
const sampleModels = [
 {name:'qwen3:1.7b',info:'Kleines Sprachmodell für einfache lokale Aufgaben.',tags:['Chat','Ollama'],status:'Beispielmodell'},
 {name:'qwen2.5-coder:7b',info:'Coding-Modell; benötigt deutlich mehr GPU-/RAM-Kapazität.',tags:['Code','Ollama'],status:'Beispielmodell'},
 {name:'nomic-embed-text',info:'Embedding-Modell für einen späteren RAG-Baustein.',tags:['Embeddings'],status:'Nicht angebunden'}
];
let toastTimer;
function notice(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3800)}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">PRIVATE AI <span style="color:#c6d0dd">/</span> ${esc(state.project.toUpperCase())}</div><h1>${esc(title)}</h1><p class="page-description">${desc}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`}
const button = (txt,cmd,style='')=>`<button class="btn ${style}" data-action="${cmd}">${txt}</button>`;
const kpi=(title,val,sub,symbol='grid',tone='')=>`<div class="card kpi"><div class="topline"><span class="kpi-name">${title}</span><span class="mini-icon ${tone}">${icon(symbol)}</span></div><div class="value">${val}</div><div class="sub">${sub}</div></div>`;
function overview(){return pageHead('Guten Morgen.','Verwalten Sie Modelle, Wissen und Agenten an einem Ort. Alle Werte dieser Ansicht sind illustrative Beispieldaten.',button(`${icon('plus')} Neuen Chat`,'newchat','primary')+button(`${icon('books')} Wissensbasis`,'knowledge'))+
 `<section class="dash-kpis" aria-label="Kennzahlen">
 ${kpi('Aktiver Modellkontext','qwen3:1.7b','Auswahl im Prototyp','cpu')}
 ${kpi('Wissensquellen',String(sampleDocs.length+state.docAdded.length).padStart(2,'0'),'Beispiel-Dokumente','books','teal')}
 ${kpi('Gedächtniseinträge',String(sampleMem.length+state.demoNotes.length).padStart(2,'0'),'Nur Browser-Demo, nicht persistent','brain')}
 ${kpi('Betriebsbereitschaft','Ungeprüft','Keine Live-Verbindung hergestellt','server','amber')}
 </section>
 <section class="dashboard-grid"><article class="card"><header class="card-head"><div><h2>Arbeitsbereiche</h2><p>Projektwissen und Agentenkontext getrennt organisieren</p></div><button class="link-button" data-action="memory">Alle anzeigen ${icon('arrow','icon-xs')}</button></header><div class="section-body">
 ${[{name:'Private AI Pipeline',info:'Basisplattform · Gateway & Gedächtnis',initial:'AI',c:''},{name:'SkyHub-Next',info:'Drohnenplattform · Projektnotizen',initial:'SH',c:'teal'},{name:'Hermes-Agent',info:'Lokaler Coding- und KI-Agent',initial:'HA',c:'purple'}].map(p=>`<button class="project-row" style="width:100%;border-left:0;border-right:0;border-top:0;background:transparent;text-align:left;cursor:pointer" data-project="${esc(p.name)}"><div class="project-logo ${p.c}">${p.initial}</div><div class="project-info"><strong>${p.name}</strong><small>${p.info}</small></div><div class="project-right">${badge('Demo')} ${icon('chevron','icon-xs')}</div></button>`).join('')}
 </div></article><article class="card"><header class="card-head"><div><h2>Systemübersicht</h2><p>Verbindung und Datenschutz im Blick</p></div><button class="link-button" data-action="system">Diagnose ${icon('arrow','icon-xs')}</button></header><div class="section-body">
 ${[['Open WebUI','Verbindung nicht geprüft','server'],['KI-Gateway','Verbindung nicht geprüft','shield'],['Ollama / Modellhost','Keine Verbindung im Prototyp','cpu'],['SQLite-Gedächtnis','Beispieldaten in Browser','harddrive']].map(x=>`<div class="health-row"><div class="health-left">${icon(x[2])}<strong>${x[0]}</strong></div>${badge('Ungeprüft','amber')}</div>`).join('')}
 <div class="health-footer">${icon('alert')} Ein echter Gesundheitsstatus erfordert die Backend-Anbindung.</div>
 </div></article></section>
 <section class="lower-grid"><article class="card"><header class="card-head"><div><h2>Zuletzt verwendete Wissensquellen</h2><p>Lokale Dateien, durchsuchbar je Projekt</p></div><button class="link-button" data-action="knowledge">Alle Dokumente ${icon('arrow','icon-xs')}</button></header>${docTable(sampleDocs.slice(0,3),true)}</article>
 <article class="card"><header class="card-head"><div><h2>Schnellaktionen</h2><p>Direkt zu häufig genutzten Aufgaben</p></div></header><div class="quick-grid">
 ${[['chat','chat','Neuen Chat beginnen','Mit lokalem Modell arbeiten'],['knowledge','upload','Wissensquelle hinzufügen','Dokumente für Suche vorbereiten'],['agents','bot','Agentenberechtigungen','Schreibrechte kontrollieren']].map(x=>`<button class="quick-action" data-action="${x[0]}"><span class="mini-icon">${icon(x[1])}</span><div><strong>${x[2]}</strong><small>${x[3]}</small></div>${icon('chevron','icon-xs')}</button>`).join('')}
 </div></article></section>`;
}
function docTable(docs,short=false){if(!docs.length)return `<div class="empty">${icon('search')}<div>Keine passenden Einträge gefunden.</div></div>`;return `<div class="table-wrap"><table class="data-table"><thead><tr><th>DATEI</th><th>PROJEKT</th><th>TYP</th>${short?'':'<th>GRÖSSE</th>'}</tr></thead><tbody>${docs.map(d=>`<tr><td><span class="file-cell">${icon('file')} ${esc(d.name)}</span></td><td>${esc(d.scope)}</td><td>${esc(d.type)}</td>${short?'':`<td>${esc(d.size)}</td>`}</tr>`).join('')}</tbody></table></div>`}
function knowledge(){const docs=[...sampleDocs,...state.docAdded].filter(d=>([d.name,d.scope,d.type].join(' ').toLowerCase().includes(state.docQuery.toLowerCase()))&&(state.docScope==='Alle'||d.scope===state.docScope));return pageHead('Wissensbasis','Projektdateien organisieren, suchen und später mit überprüfbaren Quellen in Modellantworten verwenden.',button(`${icon('upload')} Dateien hinzufügen`,'upload','primary'))+
 `<div class="projects-banner"><div><strong>Kontrollierter Dateiimport</strong><p>Dateien werden in dieser Vorschau nicht hochgeladen. Die produktive Version nutzt explizite Projekt-Namensräume.</p></div>${badge('Entwurf','blue')}</div>
 <div class="toolbar"><div class="toolbar-left"><label class="search-field">${icon('search')}<input id="docSearch" class="field" placeholder="Dateien oder Projekte suchen …" value="${esc(state.docQuery)}" aria-label="Dateien suchen"></label><select id="docScope" class="field" aria-label="Projekte filtern"><option value="Alle" ${state.docScope==='Alle'?'selected':''}>Alle Projekte</option>${['Private AI Pipeline','SkyHub-Next','Hermes-Agent'].map(x=>`<option ${state.docScope===x?'selected':''}>${x}</option>`).join('')}</select></div><span class="badge" id="docsCount">${docs.length} Einträge · Demo</span></div><div class="card" id="docsList">${docTable(docs)}</div>
 <p class="inline-warn">${icon('lock','icon-xs')} Keine Dateien verlassen Ihren Browser. Eine echte Indexierung ist in dieser Vorschau nicht integriert.</p>`}
function memory(){let items=[...sampleMem,...state.demoNotes];if(state.memFilter!=='Alle')items=items.filter(x=>x.scope===state.memFilter);return pageHead('Gedächtnis','Erinnerungen ausdrücklich erfassen, projektweise trennen und kontrolliert verwalten.',button(`${icon('plus')} Erinnerung anlegen`,'addMemory','primary'))+
 `<div class="toolbar"><div class="toolbar-left"><select id="memoryFilter" class="field" aria-label="Gedächtnisbereich">${['Alle','Private AI Pipeline','SkyHub-Next','Hermes-Agent'].map(x=>`<option ${state.memFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select>${badge('Standard: Read-only','teal')}</div><span style="font-size:11px;color:var(--muted)">${items.length} Erinnerungen · im Browser</span></div><div class="split"><div class="card">${items.map(m=>`<div class="memory-item"><span class="memory-icon">${icon('brain')}</span><div class="memory-main"><strong>${esc(m.title)}</strong><p>${esc(m.desc)}</p><div class="memory-meta">${badge(m.scope)} <span>${esc(m.time)}</span></div></div>${m.id>100?`<div class="memory-actions"><button class="icon-button" data-delete="${m.id}" aria-label="Erinnerung ${esc(m.title)} entfernen">${icon('trash')}</button></div>`:''}</div>`).join('')||'<div class="empty">Keine Einträge im gewählten Projekt.</div>'}</div><div class="card"><header class="card-head"><h2>Speicherregeln</h2></header><div class="info-list"><div class="info-row"><span>Automatische Chatspeicherung</span><strong>Aus im eigenen Memory</strong></div><div class="info-row"><span>Agenten-Schreibzugriff</span>${badge('Gesperrt','teal')}</div><div class="info-row"><span>Projektisolation</span>${badge('Entwurfsprinzip','blue')}</div><div class="info-row"><span>Persistenz in dieser Demo</span><strong>Keine</strong></div></div><div class="callout"><strong>Hinweis:</strong> Das eigenständige Memory-Modul ist nicht mit dem Chatverlauf von Open WebUI gleichzusetzen. Open WebUI kann Chats separat speichern.</div></div></div>`}
function chat(){return pageHead('KI-Chat','Ein aufgeräumter Arbeitsbereich für lokale Modelle. Das Senden funktioniert hier ausschließlich als Simulation.',button(`${icon('plus')} Neuer Chat`,'newchat','primary'))+
 `<div class="chat-layout"><aside class="card conversation-panel"><div class="card-head"><h2>Unterhaltungen</h2></div><div class="conversation-list"><button class="conversation-item active">Systemarchitektur prüfen</button><button class="conversation-item" data-action="newchat">+ Neue Unterhaltung</button></div><div class="demo-note" style="margin:9px">${icon('shield')} Kein echter Chatverlauf geladen.</div></aside>
 <section class="card chat-panel"><div class="chat-topline"><div><strong>Neue Unterhaltung</strong><div style="margin-top:5px">${badge(state.model,'blue')} ${badge('Lokale Simulation')}</div></div><select id="chatModel" class="field" aria-label="Modell wählen">${sampleModels.filter(m=>m.tags.includes('Chat')||m.tags.includes('Code')).map(m=>`<option ${state.model===m.name?'selected':''}>${m.name}</option>`).join('')}</select></div>
 <div class="chat-messages" id="chatMessages"><div class="bubble-row"><div class="bubble-avatar">${icon('spark')}</div><div><div class="bubble-meta">Private AI · Vorschau</div><div class="bubble">Guten Tag! Dies ist die lokale Designvorschau der Private AI Pipeline.\n\nHier werden später Modellantworten, durchsuchbare Quellen und explizit freigegebener Projektkontext angezeigt.</div></div></div>
 ${state.chat.map(m=>`<div class="bubble-row ${m.who==='user'?'user':''}"><div class="bubble-avatar">${m.who==='user'?'U':icon('spark')}</div><div><div class="bubble-meta">${m.who==='user'?'Sie':'Private AI · Simulation'}</div><div class="bubble">${esc(m.text)}</div></div></div>`).join('')}</div>
 <form class="chat-input-area" id="chatForm"><div class="composer"><textarea id="prompt" aria-label="Nachricht eingeben" placeholder="Frage eingeben … (Demo ohne Backend)" maxlength="2000"></textarea><button type="submit" aria-label="Nachricht simulieren">${icon('send')}</button></div><div class="composer-caption">Testoberfläche · keine Netzwerkverbindung, keine Modellinferenz, keine Speicherung</div></form></section></div>`}
function agents(){const tools=[{name:'memory_search',desc:'Im freigegebenen Projektwissen suchen',role:'Lesen',active:true},{name:'memory_remember',desc:'Neue Notiz in einem Namespace speichern',role:'Schreiben',active:false},{name:'memory_forget',desc:'Erinnerungen aus dem Speicher löschen',role:'Löschen',active:false}];return pageHead('Agenten & Freigaben','Werkzeuge für Hermes-Agent, Codex und weitere MCP-Clients mit klaren Berechtigungsgrenzen.',button(`${icon('plus')} Agent verbinden`,'agentInfo'))+
 `<div class="split"><div class="card"><header class="card-head"><div><h2>MCP-Werkzeuge</h2><p>Vorgesehene API-Funktionen und Default-Berechtigungen</p></div>${badge('Read-only Vorgabe','teal')}</header>${tools.map(t=>`<div class="setting-row" style="padding:16px 19px"><div><div style="display:flex;align-items:center;gap:8px"><strong>${esc(t.name)}</strong>${badge(t.role,t.role==='Lesen'?'teal':'amber')}</div><p>${esc(t.desc)}</p></div><button class="toggle" role="switch" aria-label="${esc(t.name)} (Simulation)" aria-checked="${String(state.tools[t.name])}" data-tool="${esc(t.name)}"></button></div>`).join('')}</div>
 <div><div class="card"><header class="card-head"><h2>Verbundene Clients</h2></header><div class="info-list"><div class="info-row"><span>Hermes-Agent</span>${badge('Nicht verbunden','amber')}</div><div class="info-row"><span>Codex CLI</span>${badge('Nicht verbunden','amber')}</div><div class="info-row"><span>MCP stdio</span><strong>Integrationsziel</strong></div></div></div><div class="callout"><strong>Wichtig:</strong> Ein Schalter in dieser Oberfläche ändert nur den Demozustand. Produktiv erzwingt ausschließlich der Backend-Dienst die Berechtigungen.</div></div></div>`}
function models(){return pageHead('Lokale Modelle','Modelle katalogisieren und einen Standard auswählen. Es findet hier kein Modelldownload statt.',button(`${icon('plus')} Ollama verbinden`,'modelInfo','primary'))+
 `<div class="demo-note" style="margin-bottom:16px">${icon('alert')} Ollama und die installierten Modellversionen werden erst nach einer echten Backend-Verbindung erkannt.</div><div class="model-grid">${sampleModels.map(m=>`<article class="card model-card ${state.model===m.name?'selected':''}"><div class="mini-icon">${icon(m.tags.includes('Embeddings')?'books':'cpu')}</div><h3>${m.name}</h3><p>${m.info}</p><div class="model-tags">${m.tags.map(t=>`<span>${t}</span>`).join('')}</div>${badge(m.status)}<button class="btn ${state.model===m.name?'soft':''}" data-model="${m.name}">${state.model===m.name?`${icon('check')} In Demo ausgewählt`:'Als Demo-Modell wählen'}</button></article>`).join('')}</div>`}
function system(){return pageHead('Systemstatus','Übersicht der geplanten Komponenten. Live-Prüfungen werden erst mit einem abgesicherten Backend verfügbar.',button(`${icon('server')} Verbindung testen`,'systemInfo'))+
 `<div class="projects-banner"><div><strong>Es besteht keine Backend-Verbindung</strong><p>Die folgenden Dienste werden als Architektur gezeigt, nicht als laufend oder erreichbar bestätigt.</p></div>${badge('Offline-Demo','blue')}</div><div class="dash-kpis">${kpi('Raspberry Pi 5','—','RAM / CPU nicht ausgelesen','server')}${kpi('Ollama-Host','—','Erreichbarkeit nicht getestet','cpu')}${kpi('Datenbank','—','Kein Zugriff auf SQLite','harddrive')}${kpi('Letztes Backup','—','Kein Backupstatus verfügbar','clock')}</div><div class="split"><div class="card"><header class="card-head"><h2>Service-Abhängigkeiten</h2></header><div class="section-body">${[['Open WebUI','Benutzeroberfläche'],['Private AI Gateway','OpenAI-kompatible lokale API'],['Ollama','Modellinferenz (LAN / Host)'],['SQLite / MCP','Lokaler Projektspeicher']].map(s=>`<div class="health-row"><div class="health-left">${icon('server')}<div><strong>${s[0]}</strong><div style="font-size:10px;color:#9ba8b6;margin-top:2px">${s[1]}</div></div></div>${badge('Nicht geprüft','amber')}</div>`).join('')}</div></div><div class="card"><header class="card-head"><h2>Datenschutz & Isolation</h2></header><div class="info-list"><div class="info-row"><span>Cloud-Fallback</span><strong>Nicht vorgesehen</strong></div><div class="info-row"><span>LAN-Zugriff</span><strong>Nach Freigabe</strong></div><div class="info-row"><span>Docker-Netz</span><strong>Internes Profil geplant</strong></div><div class="info-row"><span>Backup-Status</span>${badge('Ungeprüft','amber')}</div></div><div class="callout">Netzwerkisolation muss im produktiven Betrieb mit Firewall- und Egress-Tests geprüft werden. Der Prototyp bietet keine Sicherheitsgarantie.</div></div></div>`}
function settings(){return pageHead('Einstellungen','Anzeige und Oberfläche im Prototyp anpassen. Technische Änderungen erfolgen später ausschließlich über abgesicherte APIs.')+
 `<div class="split"><div class="card"><header class="card-head"><h2>Erscheinungsbild</h2></header><div class="setting-group"><div class="setting-row"><div><strong>Kompakte Darstellung</strong><p>Geringere Abstände in Tabellen, Navigation und Karten.</p></div><button class="toggle" role="switch" aria-label="Kompakte Darstellung" aria-checked="${state.compact}" data-setting="compact"></button></div><div class="setting-row"><div><strong>Farbschema</strong><p>Helles Design mit Blau und neutralen Oberflächen.</p></div>${badge('Hell','blue')}</div><div class="setting-row"><div><strong>Sprache</strong><p>Oberflächentexte des Designprototyps.</p></div><strong>Deutsch</strong></div></div></div><div class="card"><header class="card-head"><h2>Umgebung (Entwurf)</h2></header><div class="info-list"><div class="info-row"><span>Basisprofil</span><strong>Einzelbenutzer</strong></div><div class="info-row"><span>Gateway-Port</span><span class="token-example">38880</span></div><div class="info-row"><span>Modus</span><strong>Offline-first</strong></div><div class="info-row"><span>Standardzugriff</span><strong>Read-only</strong></div></div><div class="callout">Echte Secrets, Modelladressen und administrative Netzwerkoptionen dürfen nicht über eine frei erreichbare statische Oberfläche konfiguriert werden.</div></div></div>`}
function render(){let page=names[state.page]?state.page:'overview';$('#breadcrumb').textContent=names[page];document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#workspaceLabel').textContent=state.project;$('#view').innerHTML=({overview,chat,knowledge,memory,agents,models,system,settings}[page])();document.body.classList.toggle('compact',state.compact);document.title=names[page]+' · Private AI Pipeline';setupPageEvents()}
function route(page){if(!names[page])return;state.page=page;history.replaceState(null,'','#'+page);$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show');render();$('#view').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function setupPageEvents(){
 const updateDocuments=()=>{const filtered=[...sampleDocs,...state.docAdded].filter(d=>[d.name,d.scope,d.type].join(' ').toLowerCase().includes(state.docQuery.toLowerCase())&&(state.docScope==='Alle'||d.scope===state.docScope));if($('#docsList'))$('#docsList').innerHTML=docTable(filtered);if($('#docsCount'))$('#docsCount').textContent=filtered.length+' Einträge · Demo'};
 const ds=$('#docSearch');if(ds)ds.addEventListener('input',e=>{state.docQuery=e.target.value;updateDocuments()});
 const docScope=$('#docScope');if(docScope)docScope.addEventListener('change',e=>{state.docScope=e.target.value;updateDocuments()});
 const ms=$('#memoryFilter');if(ms)ms.addEventListener('change',e=>{state.memFilter=e.target.value;render()});
 const chatModel=$('#chatModel');if(chatModel)chatModel.addEventListener('change',e=>{state.model=e.target.value;render()});
 const chatForm=$('#chatForm');if(chatForm)chatForm.addEventListener('submit',e=>{e.preventDefault();const input=$('#prompt');const txt=input.value.trim();if(!txt)return;state.chat.push({who:'user',text:txt},{who:'bot',text:'Demo-Modus: Es wurde kein lokales Sprachmodell angesprochen und keine Nachricht gespeichert. Die spätere Anwendung wird diese Ausgabe durch eine echte lokale Modellantwort ersetzen.'});render();$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;$('#prompt')?.focus()});
}
function showModal(title,body,buttons){const root=$('#modalRoot');root.innerHTML=`<div class="modal-cover" id="modalCover"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><strong id="modalTitle">${title}</strong><button class="icon-button" id="modalClose" aria-label="Schließen">${icon('x')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${buttons}</div></div></div>`;$('#modalClose').focus()}
function closeModal(){$('#modalRoot').innerHTML=''}
function openSearch(){let items=Object.entries(names).filter(([key,v])=>v.toLowerCase().includes(state.search.toLowerCase()));showModal('Schnellnavigation',`<div class="form-row"><label class="form-label" for="cmdSearch">Bereich suchen</label><input class="field" id="cmdSearch" placeholder="Chat, Wissen, Systeme …" value="${esc(state.search)}" style="width:100%" autocomplete="off"></div><div class="cmd-list" id="cmdList">${items.map(([k,v])=>`<button class="cmd-item" data-action="${k}">${icon(k==='overview'?'grid':k==='knowledge'?'books':k==='memory'?'brain':k==='models'?'cpu':k==='agents'?'bot':k==='settings'?'settings':k==='system'?'server':'chat')}<span>${v}</span>${icon('arrow','icon-xs')}</button>`).join('')}</div>`,button('Schließen','close'));$('#cmdSearch')?.focus()}
function showMemoryModal(){showModal('Erinnerung anlegen',`<p>Einträge dieser Designvorschau verbleiben nur im flüchtigen Browser-Speicher. Kein Gateway, keine Datei und kein Modell werden angesprochen.</p><form id="memoryForm"><div class="form-row"><label class="form-label" for="memTitle">Titel</label><input class="field" id="memTitle" maxlength="120" required placeholder="z. B. Projektregel"></div><div class="form-row"><label class="form-label" for="memScope">Projekt</label><select class="field" id="memScope"><option>Private AI Pipeline</option><option>SkyHub-Next</option><option>Hermes-Agent</option></select></div><div class="form-row"><label class="form-label" for="memText">Inhalt</label><textarea class="field" id="memText" maxlength="700" required placeholder="Was darf ausdrücklich erinnert werden?"></textarea></div><button type="submit" id="hiddenSubmit" hidden></button></form>`,button('Abbrechen','close')+button('Als Demo-Notiz einfügen','saveMemory','primary'));$('#memTitle')?.focus()}
function handleAction(action){if(names[action])return route(action);switch(action){case'newchat':state.chat=[];route('chat');break;case'close':closeModal();break;case'upload':showModal('Dateiimport · Vorschau',`<p>Sie können Dateien auswählen, um deren Namen in der Demo-Liste anzuzeigen. Der Dateiinhalt wird nicht gelesen, nicht gespeichert und nicht übertragen.</p><div class="form-row"><label class="form-label" for="uploadFiles">Dateien auswählen (max. 5 Namen)</label><input type="file" id="uploadFiles" class="field" multiple accept=".md,.txt,.json,.py,.yaml,.yml" style="height:auto;padding:9px"></div><div class="demo-note">${icon('lock')} Keine tatsächliche Indexierung oder Speicherung</div>`,button('Abbrechen','close')+button('Dateinamen anzeigen','saveFiles','primary'));break;case'saveFiles':{const files=Array.from($('#uploadFiles')?.files||[]).slice(0,5);if(!files.length)return notice('Bitte eine Datei auswählen.');for(const f of files){if(!state.docAdded.find(x=>x.name===f.name))state.docAdded.push({name:f.name,scope:'Private AI Pipeline',type:'Demo-Datei',size:Math.ceil(f.size/1024)+' KB'});}closeModal();render();notice('Nur Dateinamen lokal im Demo-Zustand ergänzt.');break}
 case'addMemory':showMemoryModal();break;case'saveMemory':{const form=$('#memoryForm');if(!form.reportValidity())return;state.demoNotes.push({id:101+state.demoNotes.length,title:$('#memTitle').value.trim(),desc:$('#memText').value.trim(),scope:$('#memScope').value,time:'Gerade ergänzt · nur Browser-Demo'});closeModal();render();notice('Demo-Erinnerung eingefügt – nicht gespeichert.');break}
 case'modelInfo':showModal('Lokale Modellanbindung',`<p>Für die produktive Version soll das Gateway nur ausdrücklich freigegebene Ollama-Hosts unterstützen. Diese Vorschau verbindet sich mit keinem Server.</p><div class="demo-note">${icon('lock')} Keine Cloud-Fallbacks, keine Modellinstallation im Browser.</div>`,button('Verstanden','close','primary'));break;
 case'agentInfo':showModal('MCP-Client anbinden',`<p>Hermes-Agent und Codex werden später über einen abgesicherten MCP-Adapter angebunden. Schreibaktionen benötigen eine getrennte Backend-Policy und eine ausdrückliche Berechtigung.</p><p>Die jetzige Oberfläche kann keine Agentenprozesse starten oder verbinden.</p>`,button('Schließen','close','primary'));break;
 case'systemInfo':showModal('Systemprüfung noch nicht verfügbar',`<p>In der Designvorschau gibt es keinen Netzwerkzugriff. Für Live-Status sind ein authentifizierter Status-Endpunkt, TLS-Transport und ein datensparsames Telemetrieformat erforderlich.</p>`,button('OK','close','primary'));break;
 default: break}}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page)return route(page.dataset.page);const act=e.target.closest('[data-action]');if(act)return handleAction(act.dataset.action);const project=e.target.closest('[data-project]');if(project){state.project=project.dataset.project;notice(`Arbeitsbereich „${state.project}“ ausgewählt (Demo).`);return render()}const model=e.target.closest('[data-model]');if(model){state.model=model.dataset.model;notice(`Beispielmodell „${state.model}“ ausgewählt.`);return render()}const tool=e.target.closest('[data-tool]');if(tool){const k=tool.dataset.tool; if(k==='memory_search'){return notice('Der Lesezugriff bleibt in der Demo aktiviert.')}return showModal('Berechtigung simulieren',`<p><strong>${esc(k)}</strong> benötigt erhöhte Rechte. Die Produktivversion darf solche Schreib- oder Löschrechte ausschließlich über den Backend-Policy-Check und einen expliziten Freigabeprozess aktivieren.</p><p>Eine Bestätigung hier verändert nur die visuelle Vorschau.</p>`,button('Abbrechen','close')+`<button class="btn primary" data-grant="${esc(k)}">Visuell freigeben (Demo)</button>`)}const grant=e.target.closest('[data-grant]');if(grant){state.tools[grant.dataset.grant]=true;closeModal();render();notice('Nur UI-Demozustand aktualisiert.');return}const setting=e.target.closest('[data-setting]');if(setting){state[setting.dataset.setting]=!state[setting.dataset.setting];render();notice(state.compact?'Kompaktansicht aktiviert.':'Standardabstände aktiviert.');return}const del=e.target.closest('[data-delete]');if(del){const item=state.demoNotes.find(x=>String(x.id)===del.dataset.delete);if(item)showModal('Demo-Notiz entfernen',`<p>„${esc(item.title)}“ aus dem flüchtigen Browser-Demozustand entfernen?</p>`,button('Abbrechen','close')+`<button class="btn danger" data-confirm-delete="${item.id}">Entfernen</button>`);return}const conf=e.target.closest('[data-confirm-delete]');if(conf){state.demoNotes=state.demoNotes.filter(x=>String(x.id)!==conf.dataset.confirmDelete);closeModal();render();notice('Demo-Notiz entfernt.');return}if(e.target.id==='modalCover')closeModal()});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeModal();$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show')}if(e.key==='Enter'&&e.target.id==='workspacePicker'){e.preventDefault();$('#workspacePicker').click()}});
$('#globalSearch').addEventListener('click',openSearch);
$('#topSettings').addEventListener('click',()=>route('settings'));
$('#workspacePicker').addEventListener('click',()=>showModal('Arbeitsbereich wählen',`<div class="cmd-list">${['Persönlich','Private AI Pipeline','SkyHub-Next','Hermes-Agent'].map(x=>`<button class="cmd-item" data-workspace="${x}">${icon('books')}<span>${x}</span>${icon('chevron','icon-xs')}</button>`).join('')}</div>`,button('Schließen','close')));
document.addEventListener('click',e=>{const ws=e.target.closest('[data-workspace]');if(ws){state.project=ws.dataset.workspace;closeModal();render();notice('Projekt gewechselt (Designvorschau).')}});
document.addEventListener('input',e=>{if(e.target.id==='cmdSearch'){state.search=e.target.value.toLowerCase();$('#cmdList').innerHTML=Object.entries(names).filter(([,v])=>v.toLowerCase().includes(state.search)).map(([k,v])=>`<button class="cmd-item" data-action="${k}">${icon('grid')}<span>${v}</span>${icon('arrow','icon-xs')}</button>`).join('')||'<p style="font-size:12px;color:#9aa8b7">Keine Bereiche gefunden.</p>'}});
$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('show')});$('#scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show')});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(names[p]&&p!==state.page)route(p)});
route(names[location.hash.slice(1)]?location.hash.slice(1):'overview');
